import { useEffect, useState } from "react";
import { Table, Spinner, Alert } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("http://localhost/api/comandes");

      if (!response.ok) {
        throw new Error("Error al obtenir les comandes");
      }

      const data = await response.json();

      // ✅ CLAVE: la API devuelve { dades: [...] }
      if (Array.isArray(data.dades)) {
        setOrders(data.dades);
      } else {
        setOrders([]);
      }
    } catch (err) {
      console.error(err);
      setError("Error al obtenir les comandes");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return <Alert variant="danger">{error}</Alert>;
  }

  if (orders.length === 0) {
    return <p>No hi ha comandes disponibles.</p>;
  }

  return (
    <div className="mt-4">
      <h2>Comandes</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Client</th>
            <th>Total</th>
            <th>Estat</th>
            <th>Data</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((order) => (
            <tr key={order.id}>
              <td>{order.id}</td>
              <td>{order.nom_client ?? "-"}</td>
              <td>{order.total} €</td>
              <td>{order.estat}</td>
              <td>
                {new Date(order.created_at).toLocaleDateString("ca-ES")}
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
}

export default OrdersList;
